  <script>
    // Normalise any Arabic-Indic or Persian typed digits into Western standard digits
    function toWesternDigits(str) {
      return str
        .replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d))
        .replace(/[۰-۹]/g, d => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d));
    }

    const inputs = Array.from(document.querySelectorAll('.otp-input'));
    const verifyBtn = document.getElementById('verifyBtn');
    const resendBtn = document.getElementById('resendBtn');
    const timerValue = document.getElementById('timerValue');
    const timerContainer = document.getElementById('timerContainer');
    const toast = document.getElementById('toast');

    function checkCompletion() {
      const isComplete = inputs.every(input => input.value.trim().length === 1);
      verifyBtn.disabled = !isComplete;
    }

    inputs.forEach((input, index) => {
      // Input event handling
      input.addEventListener('input', (e) => {
        const normalized = toWesternDigits(e.target.value).replace(/\D/g, '');

        if (normalized.length > 0) {
          input.value = normalized[0];
          input.classList.add('is-filled');
          // Advance to next box if available
          if (index < inputs.length - 1) {
            inputs[index + 1].focus();
          }
        } else {
          input.value = '';
          input.classList.remove('is-filled');
        }
        checkCompletion();
      });

      // Keydown: Handle Backspace movement
      input.addEventListener('keydown', (e) => {
        if (e.key === 'Backspace' && !input.value && index > 0) {
          inputs[index - 1].focus();
          inputs[index - 1].value = '';
          inputs[index - 1].classList.remove('is-filled');
          checkCompletion();
        }
      });

      // Paste: auto-distribute across all 6 boxes
      input.addEventListener('paste', (e) => {
        e.preventDefault();
        const pasteData = (e.clipboardData || window.clipboardData).getData('text');
        const digits = toWesternDigits(pasteData).replace(/\D/g, '').slice(0, inputs.length);

        digits.split('').forEach((char, idx) => {
          if (inputs[idx]) {
            inputs[idx].value = char;
            inputs[idx].classList.add('is-filled');
          }
        });

        const nextIndex = Math.min(digits.length, inputs.length - 1);
        inputs[nextIndex].focus();
        checkCompletion();
      });
    });

    // 45-second countdown timer
    let remainingSeconds = 45;
    let timerInterval = null;

    function formatTime(seconds) {
      const mins = Math.floor(seconds / 60);
      const secs = seconds % 60;
      return `${mins}:${secs < 10 ? '0' : ''}${secs}`;
    }

    function startTimer() {
      remainingSeconds = 45;
      resendBtn.disabled = true;
      timerContainer.style.opacity = '1';
      timerValue.textContent = formatTime(remainingSeconds);

      clearInterval(timerInterval);
      timerInterval = setInterval(() => {
        remainingSeconds--;
        timerValue.textContent = formatTime(remainingSeconds);

        if (remainingSeconds <= 0) {
          clearInterval(timerInterval);
          resendBtn.disabled = false;
          timerContainer.style.opacity = '0.4';
        }
      }, 1000);
    }

    startTimer();

    function showToast(message) {
      toast.textContent = message;
      toast.classList.add('visible');
      setTimeout(() => {
        toast.classList.remove('visible');
      }, 3200);
    }

    function handleResend() {
      if (resendBtn.disabled) return;
      inputs.forEach(i => {
        i.value = '';
        i.classList.remove('is-filled');
      });
      inputs[0].focus();
      checkCompletion();
      startTimer();
      showToast('تمت إعادة إرسال رمز التحقق بنجاح');
    }

    function handleVerification() {
      const code = inputs.map(i => i.value).join('');
      if (code.length === 6) {
        verifyBtn.disabled = true;
        verifyBtn.textContent = 'جاري التحقق...';

        setTimeout(() => {
          showToast('تم التحقق بنجاح');
          verifyBtn.textContent = 'تم التأكيد ✓';
          verifyBtn.style.backgroundColor = '#0b5e42';
        }, 900);
      }
    }
  </script>
